<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import BaseAlert from '../components/BaseAlert.vue'
import BaseInput from '../components/BaseInput.vue'
import BaseSelect from '../components/BaseSelect.vue'
import PaginationControls from '../components/PaginationControls.vue'
import { addContactComment, assignContact, getContact, getContactAssignees, getContactComments, getContactHistory, getContacts, getContactStatuses, updateContactStatus, type Contact, type ContactAssignee, type ContactComment, type ContactHistory, type ContactStatus } from '../services/contacts'
import { useAuthStore } from '../stores/auth'
const auth = useAuthStore(); const contacts = ref<Contact[]>([]); const selected = ref<Contact | null>(null); const statuses = ref<ContactStatus[]>([]); const assignees = ref<ContactAssignee[]>([]); const history = ref<ContactHistory[]>([]); const comments = ref<ContactComment[]>([])
const search = ref(''); const type = ref(''); const status = ref(''); const unassigned = ref(false); const loading = ref(false); const detailLoading = ref(false); const saving = ref(false); const error = ref(''); const actionError = ref(''); const commentBody = ref(''); const meta = ref({ current_page: 1, last_page: 1, per_page: 25, total: 0 })
const canManage = computed(() => auth.hasPermission('contacts.manage')); const typeOptions = [{ label: 'Все типы', value: '' }, { label: 'Обратный звонок', value: 'callback' }, { label: 'Email', value: 'email' }, { label: 'Партнёр', value: 'partner' }]; const statusOptions = computed(() => [{ label: 'Все статусы', value: '' }, ...statuses.value.map(item => ({ label: item.name, value: item.code }))]); const assigneeOptions = computed(() => [{ label: 'Не назначен', value: '' }, ...assignees.value.map(item => ({ label: item.name, value: String(item.id) }))])
function date(value: string | null): string { return value ? new Date(value).toLocaleString('ru-RU') : '—' } function statusName(code: string): string { return statuses.value.find(item => item.code === code)?.name ?? code } function typeName(value: string): string { return typeOptions.find(item => item.value === value)?.label ?? value }
async function load(page = 1): Promise<void> { loading.value = true; error.value = ''; try { const result = await getContacts({ search: search.value, type: type.value, status: status.value, unassigned: unassigned.value }, { page }); contacts.value = result.data; meta.value = result.meta } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось загрузить обращения.' } finally { loading.value = false } }
async function select(contact: Contact): Promise<void> { detailLoading.value = true; actionError.value = ''; try { selected.value = await getContact(contact.id); [history.value, comments.value] = await Promise.all([getContactHistory(contact.id), getContactComments(contact.id)]) } catch (reason) { actionError.value = reason instanceof Error ? reason.message : 'Не удалось загрузить детали обращения.' } finally { detailLoading.value = false } }
async function changeStatus(): Promise<void> { if (!selected.value) return; saving.value = true; try { await updateContactStatus(selected.value.id, selected.value.status); await select(selected.value); await load(meta.value.current_page) } catch (reason) { actionError.value = reason instanceof Error ? reason.message : 'Не удалось изменить статус.' } finally { saving.value = false } }
async function changeAssignee(value: string): Promise<void> { if (!selected.value) return; saving.value = true; try { await assignContact(selected.value.id, value ? Number(value) : null); await select(selected.value); await load(meta.value.current_page) } catch (reason) { actionError.value = reason instanceof Error ? reason.message : 'Не удалось назначить ответственного.' } finally { saving.value = false } }
async function submitComment(): Promise<void> { if (!selected.value || !commentBody.value.trim()) return; saving.value = true; try { await addContactComment(selected.value.id, commentBody.value); commentBody.value = ''; comments.value = await getContactComments(selected.value.id) } catch (reason) { actionError.value = reason instanceof Error ? reason.message : 'Не удалось добавить комментарий.' } finally { saving.value = false } }
watch([type, status, unassigned], () => void load()); onMounted(async () => { try { statuses.value = await getContactStatuses(); if (canManage.value) assignees.value = await getContactAssignees() } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Не удалось загрузить справочники.' }; await load() })
</script>
<template><section class="mx-auto admin-page"><div class="mb-7"><p class="text-sm font-medium text-gray-500">Клиенты</p><h1 class="mt-1 text-2xl font-bold tracking-tight text-gray-900 sm:text-3xl">Обращения</h1><p class="mt-2 text-sm text-gray-500">Звонки, письма и партнёрские запросы в единой очереди обработки.</p></div><BaseAlert v-if="error" class="mb-4">{{ error }}</BaseAlert><div class="grid min-w-0 gap-5 xl:grid-cols-[minmax(0,1fr)_minmax(380px,0.9fr)]"><div class="min-w-0 rounded-xl border border-gray-200 bg-white shadow-card"><div class="grid gap-3 border-b border-gray-100 p-4 sm:grid-cols-2"><BaseInput v-model="search" searchable placeholder="Имя, телефон, email или текст" aria-label="Поиск обращений" @keyup.enter="() => load()"/><BaseSelect v-model="type" :options="typeOptions" accessible-name="Тип обращения"/><BaseSelect v-model="status" :options="statusOptions" accessible-name="Статус обращения"/><label class="flex items-center gap-2 text-sm text-gray-700"><input v-model="unassigned" type="checkbox" class="h-4 w-4 accent-primary-500">Только нераспределённые</label><button class="rounded-lg border border-gray-300 px-4 py-2.5 text-sm font-semibold text-gray-600" @click="() => load()">Найти</button></div><div class="overflow-x-auto"><table class="w-full min-w-[680px] text-left text-sm"><thead class="bg-gray-25 text-xs text-gray-500"><tr><th class="px-5 py-3">Обращение</th><th class="px-5 py-3">Контакт</th><th class="px-5 py-3">Статус</th><th class="px-5 py-3">Ответственный</th></tr></thead><tbody><tr v-if="loading"><td colspan="4" class="px-5 py-8 text-gray-500" role="status">Загрузка…</td></tr><tr v-else-if="!contacts.length"><td colspan="4" class="px-5 py-8 text-gray-500" role="status">Обращения не найдены.</td></tr><tr v-for="contact in contacts" :key="contact.id" class="border-t border-gray-100" :class="selected?.id === contact.id ? 'bg-primary-50' : ''"><td class="px-5 py-4"><button type="button" class="-m-2 rounded-lg p-2 text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary-500" :aria-label="`Открыть обращение ${contact.id}`" :aria-current="selected?.id === contact.id ? 'true' : undefined" @click="select(contact)"><span class="block font-semibold text-gray-800">{{ typeName(contact.type) }}</span><span class="mt-1 block text-xs text-gray-500">{{ date(contact.created_at) }}</span></button></td><td class="px-5 py-4"><p class="font-medium text-gray-700">{{ contact.contact.name ?? 'Без имени' }}</p><p class="mt-1 text-xs text-gray-500">{{ contact.contact.phone ?? contact.contact.email ?? '—' }}</p></td><td class="px-5 py-4"><span class="rounded-full bg-primary-50 px-2.5 py-1 text-xs font-medium text-primary-700">{{ statusName(contact.status) }}</span></td><td class="px-5 py-4 text-gray-600">{{ contact.assignee?.name ?? 'Не назначен' }}</td></tr></tbody></table></div><PaginationControls :meta="meta" :loading="loading" class="border-t border-gray-100 px-5 py-4" @change="load"/></div><aside class="min-w-0 rounded-xl border border-gray-200 bg-white shadow-card"><div v-if="detailLoading" class="p-8 text-sm text-gray-500" role="status">Загрузка деталей…</div><div v-else-if="!selected" class="p-8 text-sm text-gray-500" role="status">Выберите обращение в списке.</div><div v-else class="space-y-6 p-5"><div><p class="text-xs text-gray-500">{{ typeName(selected.type) }}</p><h2 class="mt-1 text-xl font-bold text-gray-900">Обращение #{{ selected.id }}</h2></div><BaseAlert v-if="actionError">{{ actionError }}</BaseAlert><section><h3 class="text-sm font-semibold text-gray-900">Контакт</h3><p class="mt-2 text-sm text-gray-700">{{ selected.contact.name ?? 'Без имени' }}</p><p v-if="selected.contact.phone" class="text-sm text-gray-600">{{ selected.contact.phone }}</p><p v-if="selected.contact.email" class="text-sm text-gray-600">{{ selected.contact.email }}</p><p v-if="selected.message" class="mt-3 whitespace-pre-line rounded-lg bg-gray-25 p-3 text-sm text-gray-700">{{ selected.message }}</p></section><section v-if="canManage" class="grid gap-3 rounded-lg border border-gray-200 p-4"><h3 class="text-sm font-semibold text-gray-900">Обработка</h3><BaseSelect v-model="selected.status" :options="statuses.map(item => ({ label: item.name, value: item.code }))" accessible-name="Новый статус обращения"/><button :disabled="saving" class="rounded-lg bg-primary-500 px-3 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="changeStatus">Сохранить статус</button><BaseSelect :model-value="selected.assignee ? String(selected.assignee.id) : ''" :options="assigneeOptions" accessible-name="Ответственный" @update:model-value="changeAssignee"/></section><section><h3 class="text-sm font-semibold text-gray-900">История статусов</h3><ol class="mt-3 space-y-2 border-l border-gray-200 pl-4 text-sm"><li v-for="entry in history" :key="entry.id"><p>{{ statusName(entry.from_status) }} → <b>{{ statusName(entry.to_status) }}</b></p><p class="text-xs text-gray-500">{{ entry.actor?.name ?? 'Система' }} · {{ date(entry.occurred_at) }}</p></li><li v-if="!history.length" class="text-gray-500">Изменений статуса пока нет.</li></ol></section><section><h3 class="text-sm font-semibold text-gray-900">Внутренние комментарии</h3><div class="mt-3 space-y-3"><article v-for="comment in comments" :key="comment.id" class="rounded-lg bg-gray-25 p-3 text-sm"><p class="whitespace-pre-line">{{ comment.body }}</p><p class="mt-2 text-xs text-gray-500">{{ comment.author?.name ?? 'Система' }} · {{ date(comment.created_at) }}</p></article><p v-if="!comments.length" class="text-sm text-gray-500">Комментариев пока нет.</p></div><form v-if="canManage" class="mt-3" @submit.prevent="submitComment"><label class="sr-only" for="contact-comment">Новый внутренний комментарий</label><textarea id="contact-comment" v-model="commentBody" class="w-full rounded-lg border border-gray-300 p-3 text-sm focus:border-primary-500 focus:ring-2 focus:ring-primary-100" rows="3" placeholder="Добавить внутренний комментарий"/><button :disabled="saving || !commentBody.trim()" class="mt-2 rounded-lg border border-gray-300 px-3 py-2 text-sm font-semibold text-gray-700 disabled:opacity-50">Добавить</button></form></section></div></aside></div></section></template>
